#[cfg(test)]
mod game_state_version_error_tests {
	use super::*;

	fn envelope(version: u8) -> Vec<u8> {
		let mut data = vec![0_u8; core::mem::size_of::<GameStateZc>()];
		data[..1].copy_from_slice(&[2]);
		data[1..2].copy_from_slice(&version.to_le_bytes());
		data
	}

	#[test]
	fn stale_and_future_versions_are_distinguishable() {
		let Err(error) = GameState::try_from_bytes(&envelope(1_u8)) else {
			panic!("a future envelope must fail");
		};
		assert_eq!(error, GameStateVersionError::Future { stored: 1 });
		assert_eq!(
			GameStateVersionError::Future { stored: 1 }.to_string(),
			"migration version mismatch: expected 0, received 1 (the data was written by a newer program; upgrade this client)"
		);
		assert!(
			GameState::try_from_bytes(&envelope(0_u8)).is_ok(),
			"the current version must decode",
		);
	}
}
